var e=`https://www.wensui.us`,t=t=>`${e}/wp-content/uploads/${t}`,n=[{slug:`servo-robot`,title:`Servo Robot`,summary:`Removes moulded parts and places them on a conveyor, inspection station or collection fixture.`,overview:[`A servo-driven takeout robot synchronizes its motion with the injection press. Select the travel, payload and gripper around the part and the mould opening.`],features:[`Three-axis servo motion`,`Configurable gripping and placement`,`Press and downstream equipment integration`],specs:[{label:`Wensui H series payload`,value:`12–100 kg, by model`},{label:`Vertical stroke`,value:`1,200–3,000 mm, by model`}],image:t(`2022/12/3-Axis-Robot-Arm-1-600x602.jpg`),specSource:`${e}/automation-series/h-series-servo-robot/`},{slug:`sprue-picker`,title:`Sprue Picker`,summary:`Removes sprues and runners from the open mould for transfer to a collection bin or granulator.`,overview:[`A compact swing-arm picker keeps runners separate from finished parts. Confirm the mould opening, reach and compressed-air supply before selecting the arm and gripper.`],features:[`Pneumatic swing-arm removal`,`Separate runner collection`,`Gripper matched to the mould and runner`],specs:[{label:`Wensui JR example vertical strokes`,value:`550 or 650 mm`},{label:`Maximum load`,value:`3 kg on the referenced models`}],image:`https://images.squarespace-cdn.com/content/v1/65646c33af061724a35f085b/fc338190-f3d6-44c9-8777-ddf5de58c693/Wensui%2Brobotic%2Bsprue%2Bpicker.jpg.jpg`,specSource:`https://static1.squarespace.com/static/65646c33af061724a35f085b/t/6823688feb5084092a1b074d/1747150994880/Wensui%2Bcatalog-Robot.pdf`},{slug:`belt-conveyor`,title:`Belt Conveyor`,summary:`Moves accepted parts from the injection cell to inspection, counting or packing.`,overview:[`Belt dimensions and height are selected to suit the available floor space, part weight and robot discharge position.`],features:[`Adjustable height`,`Robot discharge integration`,`Choice of belt width and conveyor length`],specs:[{label:`Wensui CB belt width`,value:`200–600 mm, by model`},{label:`Maximum belt speed`,value:`6 m/min on the referenced range`}],image:t(`2021/12/CB%E7%9A%AE%E5%B8%A6%E8%BE%93%E9%80%81%E6%9C%BA-2.png`),specSource:`${e}/automation-series/cb-belt-conveyor/`},{slug:`granulator`,title:`Granulator`,summary:`Reduces suitable sprues, runners and reject parts into regrind for controlled reuse.`,overview:[`Size the granulator around the material, scrap dimensions and expected feed rate. Confirm that the product specification permits reuse before returning regrind to production.`],features:[`Beside-the-press configurations`,`Feed matched to the type of scrap`,`Optional regrind collection and conveying`],specs:[{label:`Wensui WVGO reference throughput`,value:`15–40 kg/h across listed models`},{label:`Reference rotor speed`,value:`24 rpm`}],image:t(`2021/12/05c0f7bb3b1e48bdbab97ecb9f26df78.jpg`),specSource:`${e}/granulating-and-recycling-series/wsgo-low-speed-granulator/`},{slug:`dust-separation-system`,title:`Dust Separation System`,summary:`Separates fines from regrind and transfers the collected material after granulation.`,overview:[`Select a dust separation system around the granulator output, conveying lift and expected fines. Keep the collected fines separate from reusable material.`],features:[`Regrind collection after granulation`,`Separate dust collection`,`Granulator and conveying integration`],specs:[{label:`Wensui RFF motor range`,value:`1.5–5.5 kW, by model`},{label:`Reference conveying height`,value:`3–5 m, by model`}],image:t(`2021/12/59c43d15ceb242079eb2ccea63ccd89f.jpg`),specSource:`${e}/granulating-and-recycling-series/rff-series-dust-separating-system/`},{slug:`dehumidifier`,title:`Dehumidifier`,summary:`Supplies low-dew-point process air for drying moisture-sensitive resins such as PET.`,overview:[`Specify the drying air against resin requirements, material throughput and the connected hopper. Verify the target dew point under the expected operating conditions.`],features:[`Desiccant rotor system`,`Controlled drying temperature`,`Optional dew-point monitoring on the referenced range`],specs:[{label:`Wensui VD80H–VD300H examples`,value:`80–300 m³/h of hot-air flow`},{label:`Published dew point`,value:`Below −40 °C under specified conditions`}],image:t(`2022/12/low-energy-dehumidifier.jpg`),specSource:`${e}/drying-and-dehumidifying-series/vd-desiccant-rotor-dehumidifier/`},{slug:`hopper-dryer`,title:`Hopper Dryer`,summary:`Holds and heats resin before moulding, with drying equipment selected for the material.`,overview:[`Hopper volume and heater duty depend on the resin, residence time and throughput. Pair the hopper with dehumidified air when the resin specification calls for it.`],features:[`Temperature control`,`Material-level inspection window on the reference range`,`Machine-mounted or stand integration as configured`],specs:[{label:`Wensui WSDB rated hopper capacity`,value:`12–800 kg, based on PA6 granules`},{label:`Heating power`,value:`1.6–30 kW, by model`}],image:t(`2021/12/de8513bfbcc14e8eaeca49cdff57a213.jpg`),specSource:`${e}/drying-and-dehumidifying-series/wsdb-standard-hopper-dryer/`},{slug:`resin-auto-loader`,title:`Resin Auto-Loader`,summary:`Automatically conveys pellets to a dryer or processing machine when its hopper calls for material.`,overview:[`A vacuum receiver transfers resin from the source container and reduces routine manual handling at the press. Select the receiver and blower around the material and conveying route.`],features:[`Demand-controlled loading`,`Hopper or dryer mounting`,`Accessible filter and material shortage alarm on the reference model`],specs:[{label:`Wensui WSAL-300G reference conveying capacity`,value:`300 kg/h at catalogue conditions`},{label:`Reference lift and receiver volume`,value:`3.5 m pump lift and 6 L receiver`}],image:`/catalogue/wensui-auto-loader.webp`,imageCaption:`Wensui WSAL-300G, manufacturer selection guide.`,specSource:`${e}/feeding-and-conveying-series/wsal-300g-stand-alone-autoloader/`},{slug:`industrial-water-chiller`,title:`Industrial Water Chiller`,summary:`Supplies controlled chilled water for mould cooling and other compatible process equipment.`,overview:[`Select an air- or water-cooled system against the heat to be removed from the process. A correctly sized pump and distribution circuit deliver the required flow to each machine.`],features:[`Air- or water-cooled options`,`Controlled process-water temperature`,`Mould and plant water-circuit integration`],specs:[{label:`Wensui guide selection examples`,value:`4–30 hp compressor classes. Obtain cooling capacity in kW at design conditions.`}],image:`/catalogue/wensui-water-chiller.webp`,imageCaption:`Wensui process cooling equipment, manufacturer selection guide.`,specSource:`${e}/heating-and-cooling-series/air-and-water-chiller/`}].map(e=>({...e,category:`Auxiliary machines`})),r=[{slug:`pet-preform-injection-moulding-machine`,title:`PET Preform Injection Moulding Machine`,category:`Injection machines`,summary:`Dedicated PET presses for making preforms for water, carbonated-drink and edible-oil bottles.`,overview:[`The press fills a multi-cavity preform mould with dried PET. The mould establishes the neck finish, preform weight and geometry that the bottle-blowing process will use.`,`Compare injection units against the total PET shot, the required injection pressure and the recovery time available before the next cycle.`],features:[`Dedicated PET injection units`,`Multiple screw options by model`,`Multi-cavity mould and hot-runner integration`],specs:[{label:`Catalogue models`,value:`HMD218PET through HMD500PET`},{label:`Clamp force of the five listed models`,value:`2,180–5,000 kN`}],image:`/catalogue/hwamda-pet-preform.webp`,imageCaption:`Hwamda HMD PET platform, manufacturer catalogue.`,specSource:`https://hwamdaglobal.com/en/resources/catalogs/`,specSourceLabel:`Hwamda PET catalogue`},{slug:`pail-injection-moulding-machine`,title:`Thin-Wall Pail Injection Moulding Machine`,category:`Injection machines`,summary:`High-speed injection platforms for paint pails and other thin-wall bucket applications.`,overview:[`A pail press and mould must deliver a repeatable fill through a long, thin flow path and leave enough opening stroke to clear the finished part.`,`If the pack uses in-mould labels, check label positioning, static or vacuum retention and camera inspection with the robot and mould.`],features:[`Injection units selected for thin-wall filling`,`Mould opening and ejection sized for deep parts`,`Robot takeout and in-mould labelling integration`],specs:[{label:`Catalogue models`,value:`HMD430M8-SII through HMD800M8-SII`},{label:`Clamp force of the five listed models`,value:`4,300–8,000 kN`}],image:`/catalogue/hwamda-pail-press.webp`,imageCaption:`Hwamda HMD700M8-SII, manufacturer catalogue.`,specSource:`https://hwamdaglobal.com/en/injection-molding-machines/paint-bucket/`,specSourceLabel:`Hwamda pail-series specifications`},{slug:`aseptic-bottle-filling-machine`,title:`Aseptic Bottle Filling Machine`,category:`Liquid filling`,summary:`Controlled filling and closing for suitably processed sensitive beverages in compatible bottles.`,overview:[`The equipment decontaminates the bottle or preform and closure, maintains a hygienically controlled filling environment and receives product from a validated treatment circuit.`],features:[`Sterile-zone monitoring`,`Package and closure treatment`,`Integrated cleaning and sterilisation interfaces`],image:``},{slug:`carton-erector`,title:`Carton Erector`,category:`Packaging machines`,summary:`Forms corrugated shipping cases from flat blanks and presents them for loading.`,overview:[`The erector squares and closes the bottom of each case, then transfers the open case to the next packing station.`],features:[`Blank magazine and pick-off`,`Case squaring and bottom sealing`,`Case conveyor and packer interface`],image:``},{slug:`carton-packer`,title:`Carton Packer`,category:`Packaging machines`,summary:`Loads bottles, pouches or multipacks into shipping cases at a controlled rate.`,overview:[`The machine forms the required product group, aligns it with the case and loads the group with the configured mechanism.`],features:[`Product collation`,`Top-load, side-load or wraparound configurations`,`Sealer and inspection integration`],image:``},{slug:`automatic-palletizer`,title:`Automatic Palletizer`,category:`Packaging machines`,summary:`Stacks cases, trays or wrapped bundles in specified layers for dispatch.`,overview:[`A robot or layer palletizer builds repeatable patterns and transfers finished pallets to a wrapping or dispatch area. Specify the approved load diagrams and floor layout up front.`],features:[`Programmable patterns`,`Pack-specific gripper or layer handling`,`Safety and end-of-line controls`],image:``},{slug:`ultrafiltration-water-treatment-system`,title:`Ultrafiltration Water Treatment System`,category:`Water treatment`,summary:`Membrane filtration for source-water clarification and pretreatment.`,overview:[`A UF skid uses a physical membrane barrier to separate fine suspended material. Backwashing and membrane cleaning maintain flow at the design conditions.`],features:[`Controlled filtration and backwash`,`Membrane monitoring and integrity checks`,`Stand-alone or RO pretreatment duty`],image:``}],i=e=>`/catalogue/${e}.webp`,a=[{slug:`oop-labelling-machine`,title:`OPP Labelling Machine`,category:`Labelling machines`,summary:`A high-speed rotary system for applying hot-melt adhesive OPP labels in continuous production.`,overview:[`The machine coordinates container infeed, label cutting, adhesive application and finished-container discharge in one continuous process.`,`Glue is applied only at the label edges, which supports a neat overlap seal while limiting adhesive consumption.`],features:[`Continuous rotary operation for high-throughput lines`,`Automatic adjustment of incoming and outgoing containers`,`Servo-driven label cutting for accurate placement`,`Edge-only adhesive application to reduce glue usage`,`Tight, smooth wrapping with controlled overlap sealing`],image:i(`oop-labelling-machine`)},{slug:`shrink-packaging-machine`,title:`Shrink Packaging Machine`,category:`Packaging machines`,summary:`An automated end-of-line system for arranging bottles, wrapping film, shrinking and cooling finished bundles.`,overview:[`The system handles bottle grouping and film application before the pack enters an adjustable heat-shrink section and cooling stage.`,`Its compact layout is designed to reduce manual handling and create stable multipacks for retail or distribution.`],features:[`Automated bottle sorting, film wrapping and shrinking`,`Servo-controlled film feeding, coating and cutting`,`Adjustable airflow and outlet position in the shrink tunnel`,`Touchscreen controls for production settings`,`Compact arrangement with accessible service points`],image:i(`shrink-packaging-machine`)},{slug:`laser-coding-machine`,title:`Laser Coding Machine`,category:`Coding machines`,summary:`Non-contact marking for production codes on compatible bottles, cans and cartons.`,overview:[`The laser marks batch details, expiry dates, barcodes and QR codes directly onto the packaging surface.`,`The process marks the surface without ink or solvent. Test the proposed material and code at the intended conveyor speed.`],features:[`Permanent, legible production marks`,`Suitable for batch codes, dates, barcodes and QR codes`,`Resistant to smudging, fading and routine environmental exposure`,`Non-contact marking at production-line speed`,`No ink or solvent consumables`],image:i(`laser-coding-machine`)},{slug:`cap-compression-machine`,title:`Cap Compression Machine`,category:`Injection machines`,summary:`A rotary compression-moulding system for continuous, high-volume production of plastic closures.`,overview:[`Raw material is dosed automatically before servo-controlled compression heads form caps under consistent pressure and temperature.`,`The process is designed to produce repeatable cap weight and shape while limiting scrap and changeover time.`],features:[`Continuous rotary cap production`,`Automatic raw-material dosing and feeding`,`Servo-controlled compression heads`,`Reduced scrap through compression moulding`,`Controlled temperature and pressure for uniform caps`,`Support for multiple cap sizes, shapes and colours`,`Short heating cycles and efficient cooling`],image:i(`cap-compression-machine`)},{slug:`automatic-rotary-bottle-blowing-machine`,title:`Automatic Rotary Bottle Blowing Machine`,category:`Bottle blowing`,summary:`A high-output rotary stretch-blow platform for producing PET bottles in multiple formats.`,overview:[`The machine handles preforms continuously through the heating and blowing process, supporting stable large-scale bottle production.`,`It is presented for food and beverage, cosmetics, pharmaceutical and chemical packaging applications.`],features:[`Continuous rotary preform movement`,`Configurable for different bottle shapes and sizes`,`Designed for stable, energy-conscious production`,`PET preform and bottle handling matched to the mould and format`],specs:[{label:`E-One published machine range`,value:`8,000–36,000 bottles/hour, by model and format`}],specSource:`https://e-onemachinery.com/product/automatic-rotary-bottle-blowing-machine/`,specSourceLabel:`E-One rotary blower reference`,image:i(`automatic-rotary-bottle-blowing-machine`)},{slug:`automatic-linear-bottle-blowing-machine`,title:`Automatic Linear Bottle Blowing Machine`,category:`Bottle blowing`,summary:`An automatic linear stretch-blow machine for medium-speed PET bottle production.`,overview:[`The platform uses a rigid single-plate steel frame to support repeatable forming and long-term machine stability.`,`Its pressure-recovery arrangement reuses part of the high-pressure gas and reduces reliance on a separate low-pressure air system.`],features:[`Medium-speed linear bottle production`,`Single-piece steel frame for rigidity and precision`,`High-pressure gas recovery to reduce operating demand`,`PET preform and bottle handling with format-specific change parts`],specs:[{label:`E-One published machine range`,value:`3,000–8,000 bottles/hour, by model and format`}],image:i(`automatic-linear-bottle-blowing-machine`),specSource:`https://e-onemachinery.com/product/automatic-linear-bottle-blowing-machine/`,specSourceLabel:`E-One linear blower reference`},{slug:`carbonated-filling-machine`,title:`Carbonated Filling Machine`,category:`Liquid filling`,summary:`A DXGF rinsing, filling and capping system for soft drinks, sparkling water, beer and other carbonated products.`,overview:[`The machine combines the three core filling operations in one unit and controls bottle movement to protect fill accuracy and carbonation.`,`Its drive and handling systems are designed for stable output with low operating noise.`],features:[`Integrated washing, filling and capping`,`Precise liquid control at high production speed`,`Pneumatic bottle conveying and mouth clamping`,`Oil-nylon gear drive for stable, lower-noise operation`,`Serviceable layout for routine maintenance`],image:i(`carbonated-filling-machine`)},{slug:`barrel-filling-machine`,title:`Barrel Filling Machine`,category:`Liquid filling`,summary:`A QGF-series system for washing, filling, capping and sealing large water containers and drums.`,overview:[`The line is designed for high-volume container handling with controlled dosing, low-drip nozzles and a hygienic product path.`,`An integrated weighing option and adjustable filling speed support accurate operation across compatible container formats.`],features:[`Automated filling sequence`,`High-accuracy dosing`,`Large-container compatibility`,`Hygienic, durable construction`,`Adjustable filling speed`,`Leak-resistant, non-drip nozzles`,`Operator-oriented controls`,`Integrated weighing option`,`Automatic capping and sealing`],specs:[{label:`Primary format`,value:`19-litre water barrels, with other drums subject to configuration`}],image:i(`barrel-filling-machine`)},{slug:`bottle-water-filling-machine`,title:`Bottle Water Filling Machine`,category:`Liquid filling`,summary:`A CXGF-series automated system combining bottle rinsing, water filling and capping.`,overview:[`The machine brings the principal bottling steps into a single controlled platform for hygienic, consistent drinking-water production.`,`PLC control, bottle-mouth handling and automatic liquid-level management support reliable operation at production speed.`],features:[`Integrated rinsing, filling and capping`,`High-speed filling with stable liquid control`,`Pneumatic conveying and bottle-mouth clamping`,`Low-noise operation`,`Oil-nylon gear drive`,`PLC and touchscreen interface`,`Automatic liquid-level control`,`Machine safety controls for operators and production`],image:i(`bottle-water-filling-machine`)},{slug:`juice-filling-machine-hot-filling`,title:`Juice Filling Machine (Hot Filling)`,category:`Liquid filling`,summary:`A configurable filling platform for hygienic hot filling of juice and juice-based beverages.`,overview:[`The machine is intended for integration after juice preparation and thermal treatment, carrying heated product into compatible containers under controlled conditions.`,`Final configuration is selected around the product, container, target output and the surrounding capping and packaging equipment.`],features:[`Hot-fill process compatibility`,`Flexible line configuration`,`Integration with capping, coding and packaging equipment`,`Built for dependable commercial production`,`Project-specific output and container handling`],image:i(`juice-filling-machine-hot-filling`)},{slug:`sleeve-labelling`,title:`Sleeve Labelling Machine`,category:`Labelling machines`,summary:`An automatic machine for placing shrinkable sleeves on bottles, jars, cans and other containers.`,overview:[`Labels are cut and positioned around each container before a steam or hot-air stage shrinks the sleeve into place.`,`The format is suited to full-body decoration, tamper bands and containers that need a close-fitting label.`],features:[`Continuous high-speed labelling`,`Compatibility with multiple container shapes and sizes`,`Accurate high-speed sleeve cutting`,`Automatic label placement`,`Steam or hot-air shrinking for a secure finish`],image:i(`sleeve-labelling`)},{slug:`reverse-osmosis-ro-water-treatment-system`,title:`Reverse Osmosis Water Treatment System`,category:`Water treatment`,summary:`A configurable RO platform for removing dissolved salts, minerals and remaining impurities after pretreatment.`,overview:[`Pretreated water passes through precision filtration and RO membranes, separating purified product water from the concentrated reject stream.`,`The system can be sized for commercial or industrial water-treatment requirements and integrated upstream of beverage filling.`],features:[`High-efficiency membrane separation`,`Removal of dissolved solids after pretreatment`,`High water-recovery design`,`Corrosion-resistant stainless-steel frame`,`Capacity selected to the production requirement`],specs:[{label:`E-One published range`,value:`1–50 tonnes/hour. Confirm permeate output on the proposed feed water.`}],image:i(`reverse-osmosis-ro-water-treatment-system`),specSource:`https://e-onemachinery.com/product/reverse-osmosis-ro-water-treatment-system/`,specSourceLabel:`E-One reverse-osmosis reference`},{slug:`injection-moulding-machine`,title:`Injection Moulding Machine`,category:`Injection machines`,summary:`A servo-hydraulic injection platform for packaging, household and industrial plastic components.`,overview:[`Configurable material and mould settings support varied component designs and faster changeovers between production requirements.`,`An advanced servo motor and optimized hydraulic system are used to reduce energy demand while maintaining moulding performance.`],features:[`Broad material and product-format flexibility`,`Quick mould-change support`,`Servo-driven control`,`Optimized hydraulic system`,`Suitable for medical, packaging and consumer-goods applications`],specs:[{label:`Yizumi A6 reference clamping force`,value:`900–10,000 kN, by model`}],image:i(`injection-moulding-machine`),specSource:`https://www.yizumi.com/en/ims/A6-Advanced-And-Intelligent-Injection-Molding-Machine`,specSourceLabel:`Yizumi A6 series specifications`},{slug:`gjb-series-high-compressor-homogenize`,title:`GJB Series High-Pressure Homogenizer`,category:`Auxiliary machines`,summary:`A high-pressure processing system for distributing particles evenly and stabilizing liquid products.`,overview:[`Homogenization helps create consistent texture and reduces separation before the beverage reaches filling.`,`The machine can be integrated into beverage preparation lines where product stability and repeatable mouthfeel are required.`],features:[`High-pressure homogenization`,`Uniform particle distribution`,`Improved liquid stability and consistency`,`Integration with beverage preparation and filling lines`],image:i(`gjb-series-high-compressor-homogenize`)},{slug:`lz-1-5-type-spiral-juice-extractor`,title:`LZ-1.5 Spiral Juice Extractor`,category:`Auxiliary machines`,summary:`A spiral extraction machine for separating juice from fruit while leaving pulp and seeds behind.`,overview:[`The extractor presses prepared produce to maximize liquid recovery and produce a smoother process stream.`,`It can handle a range of soft fruit and harder produce when configured for the application.`],features:[`High-yield juice extraction`,`Pulp and seed separation`,`Low-oxidation processing intended to protect product quality`,`Support for soft fruit and firmer produce`],image:i(`lz-1-5-type-spiral-juice-extractor`)},{slug:`plate-sterilizing-equipment`,title:`Plate Sterilizing Equipment`,category:`Auxiliary machines`,summary:`A thermal-treatment system for hygienic beverage processing and microbial control before filling.`,overview:[`Plate equipment transfers heat efficiently to the product or cleaning medium as part of a controlled sterilization process.`,`It supports hygienic treatment of beverage streams and product-contact circuits before the filling stage.`],features:[`Controlled heat treatment`,`Supports microbial-risk reduction`,`Suitable for beverage process integration`,`Works with steam or hot-water systems where configured`],image:i(`plate-sterilizing-equipment`)},{slug:`qhs-drink-mixer`,title:`QHS Drink Mixer`,category:`Auxiliary machines`,summary:`A beverage-processing system for accurately combining water, syrup and CO₂ before carbonated filling.`,overview:[`The mixer combines and stabilizes recipe components so flavour, sweetness and carbonation remain consistent throughout a production run.`,`It is designed for direct integration with carbonated-drink filling equipment.`],features:[`Controlled water and syrup proportioning`,`CO₂ integration`,`Consistent recipe mixing`,`Product stabilization before filling`,`Integration with high-speed carbonated lines`],image:i(`qhs-drink-mixer`)},{slug:`dth-series-electrothermal-sugar-melting-boiler`,title:`DTH Electrothermal Sugar Melting Boiler`,category:`Auxiliary machines`,summary:`An electrically heated vessel for dissolving sugar and maintaining a uniform syrup for beverage production.`,overview:[`Controlled electric heating and mixing dissolve sugar quickly while maintaining the selected syrup temperature.`,`The process is intended to avoid localized caramelization, stabilize viscosity and supply a consistent feed to downstream blending.`],features:[`Electric process heating`,`Controlled syrup temperature`,`Homogeneous sugar dissolution`,`Mixing designed to limit caramelization`,`Integration with beverage blending systems`],image:i(`dth-series-electrothermal-sugar-melting-boiler`)},{slug:`tq-2-vacuum-deaerator`,title:`TQ-2 Vacuum Deaerator`,category:`Auxiliary machines`,summary:`A vacuum-processing unit for removing dissolved oxygen and other gases from liquid before carbonation and filling.`,overview:[`Removing oxygen limits oxidation that can affect flavour and shelf life, while reducing gas interference during CO₂ dosing.`,`Lower entrained-gas levels also help manage foam during filling and pressure imbalance in sealed packages.`],features:[`Dissolved-oxygen removal`,`Improved CO₂ dissolution efficiency`,`Foam reduction during filling`,`Support for package-pressure stability`],image:i(`tq-2-vacuum-deaerator`)},{slug:`djm-vertical-colloid-mill`,title:`DJM Vertical Colloid Mill`,category:`Auxiliary machines`,summary:`A high-shear mill for reducing particle size and producing stable emulsions, suspensions and fine pastes.`,overview:[`The mill homogenizes syrups, concentrates and flavour ingredients before carbonation or filling.`,`It can refine fruit pulp and insoluble particles while helping stabilize oil-based flavours in beverage recipes.`],features:[`High-shear particle-size reduction`,`Syrup and concentrate homogenization`,`Fine processing of fruit pulp and fibres`,`Stabilization of emulsions and suspensions`,`Food, beverage and pharmaceutical applications`],image:i(`djm-vertical-colloid-mill`)},...n,...r],o=[{slug:`bottled-water-production-line`,title:`Turnkey Bottled Water Production`,image:`/eone/bestcrown/water-combiblock.webp`,imageAlt:`Best Crown stainless-steel PET water blow–fill–cap equipment in a production facility`,imageCaption:`Best Crown integrated PET water combi-block, 2022 catalogue, pp. 1–2.`,summary:`Complete PET water production, from purification and bottle forming to filling and packing. Best Crown combi-block references reach 72,000 bottles/hour at 500 mL.`,overview:[`With Best Crown, E-One can configure a standalone rinse–fill–cap machine or an integrated blow–fill–cap combi-block. The integrated layout carries preforms through bottle formation, filling and capping in one machine, reducing intermediate empty-bottle transfers, accumulation and storage. A separate blower and filling monoblock allows more flexibility in bottle supply and layout.`,`The water-treatment system is selected from the source-water analysis and finished-product specification. The treatment train combines suitable pretreatment, advanced purification and final treatment, then supplies the filler through a clean storage and transfer system. An ozone-free water combi-block can be evaluated for qualifying mineral or spring-water projects.`,`Best Crown's filling options include gravity mechanical valves, flowmeter valves and weighing-based configurations for compatible large-volume formats. Confirm the neck finish, fill accuracy, valve selection and change parts for each bottle size.`,`Filled bottles continue through the selected sleeve or OPP labelling system. Laser coding can add production date, batch and expiry details to suitable packaging before shrink wrapping, tray packing or carton boxing.`],stages:[{title:`Treat the source water`,body:`Review the source and product specification, then select filtration, RO or other required treatment, disinfection, storage and transfer.`},{title:`Form or feed bottles`,body:`Choose in-house PET stretch blowing with either integrated filling or air conveying to a monoblock. Ready-made bottle supply can also be evaluated.`},{title:`Fill and cap`,body:`Select the rinse–fill–cap or blow–fill–cap platform and valves for bottle volume, hygienic transfer, closure integrity and target output.`},{title:`Inspect, label and pack`,body:`Check fill level and cap, apply sleeve or OPP labels and traceability codes, then shrink-wrap, carton and palletise as specified.`}],liquids:[{title:`Still drinking and purified water`,body:`The standard application. Treatment and sanitation are selected around the incoming water quality and finished product.`},{title:`Mineral and spring water`,body:`Best Crown lists both mineral and spring water among its PET water applications, including a dedicated ozone-free option. Preserve the required product profile and select the approved treatment.`},{title:`Still enhanced water`,body:`Added minerals, electrolytes or flavour can change the blending, cleaning and filling requirements. Share the recipe and storage instructions before configuring the line.`}],relatedMachines:[`automatic-linear-bottle-blowing-machine`,`automatic-rotary-bottle-blowing-machine`,`bottle-water-filling-machine`,`reverse-osmosis-ro-water-treatment-system`,`ultrafiltration-water-treatment-system`,`oop-labelling-machine`,`sleeve-labelling`,`laser-coding-machine`,`shrink-packaging-machine`,`carton-packer`,`automatic-palletizer`]},{slug:`carbonated-drink-production-line`,title:`Turnkey Carbonated Drink Production`,image:`/eone/bestcrown/carbonated-pet.webp`,imageAlt:`Best Crown PET carbonated drink blowing, filling and capping combination machine`,imageCaption:`Best Crown PET CSD blow–fill–cap combination system, 2022 catalogue, p. 14.`,summary:`Pressure filling for soft drinks and sparkling beverages in PET bottles, with Best Crown combi-block capacity references up to 54,000 BPH at 500 mL.`,overview:[`A complete soft-drink line brings together source-water treatment, syrup preparation, proportioning, product cooling, carbonation and pressure filling. Pure sparkling-water recipes can use a different blending arrangement from flavoured soft drinks. The treated drink is delivered to the filler at the agreed product conditions.`,`Best Crown's PET CSD combi-block integrates bottle formation with isobaric filling and capping. It offers equal-pressure mechanical or flowmeter valves by configuration. In the supported bottle range, match the preform, pressure-rated bottle and closure to the carbonated product.`,`For sensitive carbonated and still beverages, Best Crown also references a dual-purpose aseptic platform with flowmeter filling and aseptic servo capping. Its hygiene and product-treatment requirements must be assessed for the actual recipe and intended shelf life.`,`The finished bottle moves through inspection, labelling, coding, accumulation and secondary packing. E-One reviews foam, CO₂ retention, fill accuracy and cap performance using the actual drink and package before agreeing the completed-line output.`],stages:[{title:`Prepare the drink`,body:`Treat water, prepare syrup where required, blend the recipe and configure the deaeration, cooling and carbonation equipment.`},{title:`Form the pressure-rated bottle`,body:`Match PET preforms, bottle moulds and neck finish to the product, cap and integrated or separate blowing arrangement.`},{title:`Fill under pressure`,body:`Select the isobaric valve technology and matched capper around the beverage carbonation, temperature, foam behaviour and output.`},{title:`Inspect and pack`,body:`Check fill, closure and codes, label the containers, then shrink-wrap or carton for dispatch.`}],liquids:[{title:`Carbonated soft drinks`,body:`Cola, citrus and other flavoured sodas can use a syrup-mixing and carbonation setup matched to the recipe.`},{title:`Sparkling mineral and soda water`,body:`The Best Crown PET CSD catalogue includes sparkling mineral water and sparkling soda. Confirm the product CO₂ target and pressure-rated bottle.`},{title:`Carbonated juice and sensitive drinks`,body:`Sparkling juice and other sensitive formulations require a review of acidity, particles, foam and the filling hygiene route before selecting the platform.`},{title:`Malt and other foam-sensitive beverages`,body:`Evaluate compatibility, oxygen control, product treatment and pack performance for these recipes before agreeing a line configuration.`}],relatedMachines:[`reverse-osmosis-ro-water-treatment-system`,`qhs-drink-mixer`,`tq-2-vacuum-deaerator`,`dth-series-electrothermal-sugar-melting-boiler`,`automatic-rotary-bottle-blowing-machine`,`carbonated-filling-machine`,`oop-labelling-machine`,`sleeve-labelling`,`laser-coding-machine`,`shrink-packaging-machine`,`carton-packer`,`automatic-palletizer`]},{slug:`aseptic-production-line`,title:`Turnkey Aseptic Beverage Production`,image:`/eone/bestcrown/aseptic-gwjx.webp`,imageAlt:`Best Crown GWJX dry aseptic PET blow–fill–cap combination equipment`,imageCaption:`Best Crown GWJX dry aseptic PET combi-block, 2022 catalogue, p. 6.`,summary:`Sensitive-beverage processing and aseptic PET filling with Best Crown dry aseptic combi-block and cold-fill monoblock configurations.`,overview:[`E-One works with Best Crown to configure the product-treatment and filling system around the intended beverage. A validated thermal process prepares the product, and a controlled product circuit transfers it to the filling zone. Package and closure treatment, filling-zone management and seal integrity are integral to the delivery scope.`,`Best Crown's GWJX dry aseptic combi-block integrates PET bottle formation, package preparation, filling and closing. Its aseptic cold-fill monoblock can be evaluated where bottles are formed separately. The manufacturer also offers an ultra-clean platform for suitable products with different treatment and distribution requirements.`,`Choose the filling valve and equipment configuration around actual pH, viscosity, fibres or particles. Low-acid milk and protein beverages need a different validated treatment scope from many acidic juices. The catalogue includes both flowmeter and electronic weighing configurations for aseptic filling.`,`Agree the process and packaging validation, cleaning and sterilisation interfaces, monitoring, product changeovers and acceptance testing with the project team. Confirm finished-product quality and shelf life under the intended storage conditions before commercial release.`],stages:[{title:`Prepare the beverage`,body:`Balance product blending, homogenisation or filtration with the specified recipe and processing flow.`},{title:`Treat and transfer`,body:`Use the validated product-treatment process, controlled transfer and any necessary hygienic buffer arrangement for the selected filler.`},{title:`Prepare bottle and closure`,body:`Choose the integrated PET blowing or separate bottle supply arrangement with packaging treatment and controlled filling-zone interfaces.`},{title:`Fill, close and verify`,body:`Choose the valve and capper for the product and bottle. Inspect, label, code and pack under the approved product and packaging programme.`}],liquids:[{title:`Juice, NFC and nectar`,body:`Fruit juice, not-from-concentrate (NFC) products and nectars need a review of acidity, pulp, fibres, oxygen sensitivity and product-treatment requirements.`},{title:`Tea and functional beverages`,body:`Select the filling route for the tea extract, flavour, sweetener and heat sensitivity. Confirm the intended storage temperature and package before selecting the equipment.`},{title:`Milk and plant-based drinks`,body:`Evaluate UHT and aseptic packing for a long-life format, including heat stability, formulation and allergen changeovers.`},{title:`Drinkable yoghurt`,body:`Evaluate smooth, pumpable formulations. Confirm viscosity, culture requirements and distribution temperature. Spoonable yoghurt may need a different process and filler.`}],relatedMachines:[`aseptic-bottle-filling-machine`,`plate-sterilizing-equipment`,`gjb-series-high-compressor-homogenize`,`tq-2-vacuum-deaerator`,`sleeve-labelling`,`laser-coding-machine`,`carton-packer`,`automatic-palletizer`]},{slug:`barrel-water-production-line`,title:`Barrel Water Production Line`,image:`/eone/bestcrown/barrel-filling.webp`,imageAlt:`Best Crown five-gallon DG5 barrel washing, filling and capping machine`,imageCaption:`Best Crown DG5 five-gallon water filling system, 2022 catalogue, p. 4.`,summary:`Automatic washer, filler and capper for 12–19 L containers. Best Crown DG5 reference output ranges from 600 to 3,000 barrels/hour at 18.9 L.`,overview:[`Best Crown's DG5 production line combines automatic barrel washing, filling and capping. E-One selects a returnable-container layout around the condition of incoming barrels, de-capping and inspection needs, wash sequence, available floor space and clean transfer route.`,`The product-water system is sized for large-volume filling plus washing and rinsing consumption. Treatment may include appropriate filtration, reverse osmosis and final water-quality controls according to the source and finished product.`,`The catalogue references mechanical, flowmeter and ultrasonic-positioning valve options for different barrel-filling requirements. Specify container height, neck, cap and fill measurement before selecting the filler and handling parts.`,`The capped barrels are checked, coded where the pack supports it and routed to clean finished-stock handling for home, office or commercial dispenser distribution.`],stages:[{title:`Inspect and prepare barrels`,body:`Sort new and returned containers, remove used closures where required and reject unsuitable or damaged barrels.`},{title:`Wash and supply water`,body:`Match the validated external and internal cleaning sequence, rinsing, water treatment and buffer supply to the barrel condition.`},{title:`Fill and cap`,body:`Select the DG5 configuration and valve type for the actual 12–19 L pack, fill accuracy and compatible dispenser closure.`},{title:`Inspect and dispatch`,body:`Check fill and cap integrity, add approved traceability marks and move finished barrels to clean storage.`}],liquids:[{title:`Purified and drinking water`,body:`Configure the treatment and washing programme against source-water analysis and the finished dispenser-water requirements.`},{title:`Mineral and spring water`,body:`Best Crown lists mineral and spring water as DG5 applications. Confirm the approved treatment and product-quality parameters for the source.`}],relatedMachines:[`barrel-filling-machine`,`reverse-osmosis-ro-water-treatment-system`,`laser-coding-machine`]},{slug:`dairy-milk-production-line`,title:`Dairy Milk Production Line`,image:`/eone/bestcrown/dairy-ultra-clean.webp`,imageAlt:`Best Crown ultra-clean PET liquid dairy beverage filling equipment`,imageCaption:`Best Crown ultra-clean liquid dairy filling unit, 2022 catalogue, pp. 17–18.`,summary:`Integrated processing and hygienic bottled dairy filling, including Best Crown ultra-clean cold-chain configurations and project-specific aseptic routes.`,overview:[`A dairy project starts with milk reception, testing, chilling, clarification and standardisation. Configure blending, homogenisation and the validated thermal process around the fat and protein content, intended texture, product sensitivity and output.`,`Best Crown's ultra-clean liquid dairy filling line is designed for cold-chain products including pasteurised milk, fermented yoghurt and active probiotic beverages. It references PET or PP bottles with tamper-evident caps and non-contact filling valves. E-One evaluates the bottle infeed, closure, hygienic transfer and chilled distribution arrangements for the intended product.`,`For long-life ambient products, scope the UHT process and aseptic filling route together, including the packaging barrier, product transfer and validation. The selected recipe and storage requirements determine whether the chilled or ambient system is appropriate.`,`Confirm the filling machine, sanitary circuits, monitoring and changeover arrangements. Finish the product with suitable labels, traceability codes, case packing and cold or ambient transport arrangements according to the approved distribution plan.`],stages:[{title:`Receive and standardise`,body:`Test, chill, clarify and adjust raw milk or prepared ingredients to the target composition.`},{title:`Homogenise and heat-treat`,body:`Set the homogenisation duty and thermal treatment for the recipe and intended shelf life.`},{title:`Prepare product and pack`,body:`Choose chilled holding or the validated aseptic circuit, compatible bottle supply, closure and hygiene requirements.`},{title:`Fill and distribute`,body:`Use the selected ultra-clean or aseptic configuration, then inspect, code and pack for the agreed storage and distribution conditions.`}],liquids:[{title:`Pasteurised milk and milk drinks`,body:`Best Crown's chilled dairy range supports evaluation of fresh pasteurised milk and suitable flavoured milk products with a controlled cold chain.`},{title:`Drinkable yoghurt and probiotics`,body:`Review the viscosity, live-culture requirements and refrigeration programme for smooth drinkable yoghurt or active probiotic formulations.`},{title:`Long-life milk and protein beverages`,body:`Evaluate the separate UHT and aseptic route for suitable low-acid liquids and validated ambient storage.`}],relatedMachines:[`plate-sterilizing-equipment`,`gjb-series-high-compressor-homogenize`,`aseptic-bottle-filling-machine`,`sleeve-labelling`,`laser-coding-machine`,`carton-packer`,`automatic-palletizer`]},{slug:`juice-production-line`,title:`Juice Production Line`,image:`/eone/bestcrown/hot-fill-juice.webp`,imageAlt:`Best Crown enclosed PET hot-fill beverage production equipment`,imageCaption:`Best Crown PET hot-fill production line, 2022 catalogue, p. 9.`,summary:`Complete production for juice, tea, nectar and fruit-containing drinks, with hot-fill, ultra-clean and fruit-particle configurations.`,overview:[`E-One configures the preparation section for fresh-fruit extraction, concentrate dilution or ready-prepared ingredients. Treatment of process water, recipe blending, sugar or flavour dosing, deaeration and homogenisation are selected for the required beverage quality and texture.`,`Best Crown's enclosed PET hot-fill line integrates the filling and closing operations with PLC control, a filling-temperature control system and cleaning interfaces. The hot-fill configuration requires a bottle and closure suitable for the approved temperature and cooling cycle.`,`For beverages containing fruit pieces, Best Crown provides a small-particle filling model and a larger-particle configuration using separate fruit and liquid dosing. Its catalogue differentiates products below 5 mm from larger pieces above 5 mm and below 15 mm. Select the valve, neck finish, product handling and capacity around the actual formulation.`,`The ultra-clean and aseptic routes are additional technology choices for suitable NFC juices, teas and protein drinks. Product trials determine the validated heat treatment, filling duty, packaging and intended storage. Finished packs then pass to inspection, labelling, coding and secondary packing.`],stages:[{title:`Prepare ingredients`,body:`Use suitable fruit preparation and extraction or concentrate blending. Establish the water and ingredient quality for each SKU.`},{title:`Blend and treat`,body:`Configure deaeration, ingredient dosing, homogenisation when appropriate and the validated thermal process.`},{title:`Choose the filling route`,body:`Select hot-fill, ultra-clean or aseptic equipment based on the recipe and shelf-life goal. Match particle handling and bottle design to the product.`},{title:`Inspect, cool and pack`,body:`Apply the required cooling and handling arrangement, verify closures and fill, then label, code, carton or shrink-wrap for distribution.`}],liquids:[{title:`Juices and nectars`,body:`Pure juice, juice drinks, nectars and NFC beverages may require different extraction or blending steps and treatment conditions.`},{title:`Tea and functional drinks`,body:`Best Crown references tea and functional beverages within its hot-fill range. Review extraction, recipe consistency and heat sensitivity.`},{title:`Fruit-particle beverages`,body:`Choose the small or large fruit-particle configuration after checking the actual piece size, bottle neck, texture and mixing behaviour.`},{title:`Protein and sensitive drinks`,body:`Evaluate the appropriate ultra-clean or aseptic filling route and thermal process for the formulation and intended shelf life.`}],relatedMachines:[`lz-1-5-type-spiral-juice-extractor`,`djm-vertical-colloid-mill`,`tq-2-vacuum-deaerator`,`plate-sterilizing-equipment`,`juice-filling-machine-hot-filling`,`aseptic-bottle-filling-machine`,`sleeve-labelling`,`laser-coding-machine`,`shrink-packaging-machine`,`carton-packer`,`automatic-palletizer`]},{slug:`plastic-injection-cap-compression-machines`,title:`Total Injection Machines`,image:`/eone/plastic-injection.webp`,summary:`Complete plastics production cells for PET preforms, caps, pails, thin-wall packaging and other moulded components.`,overview:[`The portfolio combines injection moulding for PET preforms and other components with compression moulding for beverage and packaging caps.`,`Machine configuration is selected around material, mould, part geometry, cycle requirements and the required level of production flexibility.`,`Applications extend across beverage, edible oil, personal care, household and industrial packaging.`],stages:[{title:`Define the component`,body:`Confirm resin, geometry, tolerances, colour and expected production volume.`},{title:`Select the process`,body:`Choose injection moulding for preforms and components or compression moulding for closures.`},{title:`Engineer the mould`,body:`Match the machine, mould and utilities to the component and cycle target.`},{title:`Commission production`,body:`Validate part quality, repeatability, handling and operator procedures.`}],relatedMachines:[`pet-preform-injection-moulding-machine`,`injection-moulding-machine`,`pail-injection-moulding-machine`,`cap-compression-machine`]},{slug:`edible-oil-filling-machines`,title:`Edible Oil Filling Machines`,image:`/eone/edible-oil-line.webp`,summary:`Configurable filling and packaging systems for vegetable, palm, sunflower, soybean, groundnut and specialty oils.`,overview:[`The filling system can be engineered for PET or glass bottles, HDPE jerry cans, pouches and metal tins across small retail and bulk formats.`,`The Best Crown catalogue includes PET oil-bottle formation within its rotary blow-moulding applications. For in-house bottle supply, evaluate the blow mould, preform, bottle geometry and closure before matching the bottle output to E-One's oil filling project.`,`Semi-automatic arrangements use operator bottle placement for lower or moderate output. Fully automatic lines add conveyors, controlled nozzles and PLC/HMI operation for higher throughput.`,`Labelling, coding and secondary packaging can be integrated around the selected container and route to market.`],stages:[{title:`Define the oil and pack`,body:`Confirm product viscosity, container material, size and closure.`},{title:`Select automation`,body:`Choose operator-assisted or fully automatic handling around the target output.`},{title:`Fill accurately`,body:`Configure the nozzle and dosing method for clean filling with controlled product loss.`},{title:`Finish the pack`,body:`Add capping, labelling, traceability coding and secondary packaging.`}],relatedMachines:[`automatic-rotary-bottle-blowing-machine`,`oop-labelling-machine`,`laser-coding-machine`,`shrink-packaging-machine`,`carton-packer`]},{slug:`moulds`,title:`Moulds`,image:`/eone/hero-moulds.webp`,summary:`Precision moulds specified around your product drawing, resin, machine and target cycle.`,overview:[`E-One works with its mould technology partner to scope tooling for PET preforms, closures and custom plastic components. Start with a drawing or sample, material grade, expected volume and the proposed production machine.`,`A mould design review covers cavity balance, cooling, ejection and maintenance access. For preforms and caps, verify the neck finish and mating dimensions so the tooling fits the bottle and closure system.`,`Agree on sample approval and acceptance criteria up front. Trial parts let the team check critical dimensions, weight and finish against the drawing before releasing the tool to production.`],stages:[{title:`PET preform moulds`,body:`Match preform weight, neck finish and cavity count to the injection press and downstream bottle design.`},{title:`Closure moulds`,body:`Specify thread, sealing geometry and any tamper-evident features around the intended bottle neck.`},{title:`Custom component moulds`,body:`Review wall thickness, surface finish, tolerances, parting lines and ejection for the target component.`},{title:`Bottle blowing moulds`,body:`Match the mould to the bottle drawing, cavity layout and linear or rotary blow-moulding machine.`}],relatedMachines:[`pet-preform-injection-moulding-machine`,`injection-moulding-machine`,`pail-injection-moulding-machine`,`cap-compression-machine`,`automatic-linear-bottle-blowing-machine`]},{slug:`turnkey-beverage`,title:`Turnkey Beverage Solutions`,image:`/eone/bestcrown/turnkey-conveying.webp`,imageAlt:`Best Crown integrated beverage production facility with stainless-steel bottle conveyors and processing equipment`,imageCaption:`Best Crown complete-line conveyor arrangement, 2022 equipment catalogue, p. 23.`,summary:`E-One and Best Crown deliver integrated beverage line configurations for bottled water, carbonated drinks, juice, aseptic beverages and dairy.`,overview:[`Langfang BestCrown Packing Machinery Co., Ltd. is E-One's beverage filling technology partner. Its catalogue covers complete PET drinking-water, carbonated-beverage, fruit juice, tea, protein drink and dairy production systems, with clean, ultra-clean and aseptic filling options.`,`E-One combines the beverage preparation, bottle formation, filling and downstream equipment around the required finished-pack rate. Choose an integrated blow–fill–cap combi-block where it fits the product and capacity, or a filling monoblock with a separate bottle supply arrangement.`,`Project planning includes the raw-material and product-property review, bottle and closure drawings, equipment layout, utilities and changeover arrangements. Agree the operating targets, inspection requirements, acceptance programme, commissioning and operator training scope before ordering.`],stages:[{title:`Prepare water and ingredients`,body:`Analyse the water source and recipe, then configure process-water treatment, blending and thermal or carbonation equipment as needed.`},{title:`Form or feed the package`,body:`Choose the PET blowing system, compatible container infeed and matched preform, mould and closure arrangement.`},{title:`Fill and close`,body:`Select water, isobaric, hot-fill, ultra-clean or aseptic filling technology around the product, hygiene requirements and target speed.`},{title:`Inspect and dispatch`,body:`Integrate label, code and fill inspection, conveyors, film or carton packing and palletising for the expected finished throughput.`}],subsolutions:[`bottled-water-production-line`,`carbonated-drink-production-line`,`aseptic-production-line`],relatedMachines:[]}],s=[`plastic-injection-cap-compression-machines`,`moulds`,`turnkey-beverage`],c={"All machines":`All Machines`,"Auxiliary machines":`Ancillary Machines`,"Bottle blowing":`Bottle Blowing Machine`,"Coding machines":`Coding Machines`,"Injection machines":`Injection Machines`,"Labelling machines":`Labelling Machines`,"Liquid filling":`Liquid Filling Machine`,"Packaging machines":`Packaging Machines`,"Water treatment":`Water Treatment`},l=[`All machines`,`Auxiliary machines`,`Bottle blowing`,`Coding machines`,`Injection machines`,`Labelling machines`,`Liquid filling`,`Packaging machines`,`Water treatment`],u=e=>a.find(t=>t.slug===e),d=e=>o.find(t=>t.slug===e);export{s as a,n as c,a as i,l as n,d as o,c as r,o as s,u as t};